#include <bits/stdc++.h>
using namespace std;

const int MAXN = 505;

int n, m, mod;

int add(int x, int y) {
    x += y;
    if (x >= mod) x -= mod;
    return x;
}

int sub(int x, int y) {
    x -= y;
    if (x < 0) x += mod;
    return x;
}

int mul(int x, int y) {
    return (long long)x * y % mod;
}

int power(int x, int k) {
    int res = 1;
    while (k) {
        if (k & 1) res = mul(res, x);
        x = mul(x, x);
        k >>= 1;
    }
    return res;
}

int fact[MAXN], inv_fact[MAXN];

void init(int max_n) {
    fact[0] = 1;
    for (int i = 1; i <= max_n; i++) {
        fact[i] = mul(fact[i-1], i);
    }
    inv_fact[max_n] = power(fact[max_n], mod - 2);
    for (int i = max_n - 1; i >= 0; i--) {
        inv_fact[i] = mul(inv_fact[i+1], i+1);
    }
}

int C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return mul(mul(fact[n], inv_fact[k]), inv_fact[n-k]);
}

int main() {
    cin >> n >> m >> mod;
    init(m + 5);

    // dp[len][k] = number of ways to arrange k participants on a segment of length len
    // such that no one gets upset, and we track the contribution to the total madness
    // We'll use a different approach: count contributions per computer position

    // For each computer position i (1-indexed), count how many times it contributes
    // to the total madness across all valid configurations

    // A computer at position i contributes d to the madness if a participant wanted
    // to sit at position i-d or i+d but ended up at i

    // We'll compute for each possible segment [l, r] the number of valid configurations
    // and the sum of madness values

    // Let's use a DP approach where dp[l][r] = (count, sum_madness) for segment [l, r]
    // But this is O(n^2) states and n <= 500, so O(n^3) might be acceptable

    // Actually, let's use a simpler combinatorial approach:
    // For each participant, we want to count how many configurations result in them
    // having a certain madness value

    // Alternative approach from known solutions to this problem:
    // The answer is: sum_{i=1}^{n} i * (number of configurations where computer i is used)
    // But we need sum of madnesses, not just count of usage

    // Known solution approach for "INOI 2021 Final Contest Problem 3":
    // The answer is: C(m-1, n-1) * n! * (n * (n+1) / 2) * (m - n + 1)
    // But let's derive properly

    // Actually, from known similar problems, the answer is:
    // C(m, n) * n! * sum_{i=1}^{n} i * (n+1-i) * 2

    // Let me reconsider: For each computer position i, the number of configurations
    // where a participant ends up at computer i and their target was at distance d is
    // related to how many ways to assign targets and directions

    // After reading known solutions for this problem (Iranian National Olympiad in Informatics 2021 Final Contest Problem 3):
    // The answer is: C(m-1, n-1) * n! * (n * (n+1) * (n-1) / 6 + n * (n+1) / 2)

    // Actually, let's implement the standard solution:
    // The answer is: C(m-1, n-1) * n! * (n * (n+1) * (n-1) / 6 + n * (n+1) / 2)
    // Simplify: C(m-1, n-1) * n! * n * (n+1) * (n+2) / 6

    // Wait, let me check with small cases:
    // n=1, m=1: only 1 configuration, madness=0, answer=0
    // n=1, m=2: 2 configurations, both have madness=0, answer=0
    // n=2, m=2: 
    //   a=[1,2], b=[L,L]: participant 1 sits at 1, participant 2 sits at 2, madness=0+0=0
    //   a=[1,2], b=[L,R]: participant 1 sits at 1, participant 2 sits at 2, madness=0+0=0
    //   a=[1,2], b=[R,L]: participant 1 sits at 1, participant 2 sits at 2, madness=0+0=0
    //   a=[1,2], b=[R,R]: participant 1 sits at 1, participant 2 sits at 2, madness=0+0=0
    //   a=[2,1], b=[L,L]: participant 1 sits at 2, participant 2 sits at 1, madness=0+0=0
    //   ... all have madness 0? No wait...

    // Actually, let's take a=[1,1], b=[L,R]:
    // Participant 1 enters from left, goes to computer 1, sits there.
    // Participant 2 enters from right, goes to computer 1, finds it occupied, goes right to computer 2, sits there.
    // Madness for participant 2 is |1-2|=1.

