    // b=[R,L]: p1 sits at 1, p2 sits at 2. Madness: 0+0=0
    // b=[R,R]: p1 sits at 1, p2 sits at 2. Madness: 0+0=0
    // Total for a=[1,2]: 4 * 0 = 0

    // Case 4: a=[2,1]
